# [doc = " Calling convention to determine codegen"] # [doc = ""] # [doc = " CanonAbi erases certain distinctions ExternAbi preserves, but remains target-dependent."] # [doc = " There are still both target-specific variants and aliasing variants, though much fewer."] # [doc = " The reason for this step is the frontend may wish to show an ExternAbi but implement that ABI"] # [doc = " using a different ABI than the string per se, or describe irrelevant differences, e.g."] # [doc = " - extern \"system\""] # [doc = " - extern \"cdecl\""] # [doc = " - extern \"C-unwind\""] # [doc = " In that sense, this erases mere syntactic distinctions to create a canonical *directive*,"] # [doc = " rather than picking the \"actual\" ABI."] # [derive (Copy , Clone , Debug)] # [derive (PartialOrd , Ord , PartialEq , Eq , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum CanonAbi { C , Rust , RustCold , # [doc = " An ABI that rustc does not know how to call or define."] Custom , # [doc = " ABIs relevant to 32-bit Arm targets"] Arm (ArmCall) , # [doc = " ABI relevant to GPUs: the entry point for a GPU kernel"] GpuKernel , # [doc = " ABIs relevant to bare-metal interrupt targets"] Interrupt (InterruptKind) , # [doc = " ABIs relevant to Windows or x86 targets"] X86 (X86Call) , }
